import json
from urllib.request import Request, urlopen


def main() -> None:
    url = "https://httpbin.org/post"
    payload = {"message": "Hello from Python", "count": 42}
    data = json.dumps(payload).encode("utf-8")
    headers = {
        "X-Test-Header": "value123",
        "Content-Type": "application/json",
