module benchmark/solution

import std/fs (writeFile, readFile)
import std/json (Json, decode, getString, getInt, getStringArrayOrEmpty)
import std/list (length)
import std/string (chars)
import std/option (Some, None)
import std/result (Ok, Err)

type Config = {app_name: string, version: string, port: int, features: [string]}
type Outcome[a] = Success(a) | Failure(string)

pure func countDots(cs: [string]) -> int =
  match cs {
    [] => 0,
    c :: rest => if c == "." then 1 + countDots(rest) else countDots(rest)
  }

pure func validVersion(version: string) -> bool =
  countDots(chars(version)) == 2

pure func validPort(port: int) -> bool =
  port >= 1024 && port <= 65535

pure func validFeatures(features: [string]) -> bool =
  match features {
    [] => false,
    _ :: _ => true
  }

pure func validateConfig(config: Config) -> Outcome[Config] =
  if not validPort(config.port) then Failure("Invalid port")
  else if not validVersion(config.version) then Failure("Invalid version")
  else if not validFeatures(config.features) then Failure("Invalid features")
  else Success(config)

pure func buildConfig(json: Json) -> Outcome[Config] =
  match getString(json, "app_name") {
    Some(appName) => match getString(json, "version") {
      Some(version) => match getInt(json, "port") {
        Some(port) => {
          let features = getStringArrayOrEmpty(json, "features");
          validateConfig({app_name: appName, version: version, port: port, features: features})
        },
        None => Failure("Missing port")
      },
      None => Failure("Missing version")
    },
    None => Failure("Missing app_name")
  }

func loadConfig(path: string) -> Outcome[Config] ! {FS} {
  let content = readFile(path);
  match decode(content) {
    Ok(json) => buildConfig(json),
    Err(msg) => Failure("Invalid JSON: ${msg}")
  }
}

pure func renderConfig(config: Config) -> string =
  "Loaded ${config.app_name} v${config.version} on port ${config.port} with ${length(config.features)} features"

export func main() -> () ! {IO, FS} {
  let configText = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}";
  writeFile("app_config.json", configText);
  match loadConfig("app_config.json") {
    Success(config) => println(renderConfig(config)),
    Failure(msg) => println(msg)
  }
}

