package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

type Config struct {
	AppName  string   `json:"app_name"`
	Version  string   `json:"version"`
	Port     int      `json:"port"`
	Features []string `json:"features"`
}

func main() {
	if err := writeConfigFile("app_config.json"); err != nil {
		return
	}

	cfg, err := loadAndValidateConfig("app_config.json")
	if err != nil {
		return
	}

	fmt.Printf("Loaded %s v%s on port %d with %d features\n", cfg.AppName, cfg.Version, cfg.Port, len(cfg.Features))
}

func writeConfigFile(path string) error {
	cfg := Config{
		AppName:  "MyApp",
		Version:  "1.0.0",
		Port:     8080,
		Features: []string{"logging", "auth", "api"},
	}

	data, err := json.Marshal(cfg)
	if err != nil {
		return err
	}

	if err := os.WriteFile(path, data, 0644); err != nil {
		return err
	}

	return nil
}

func loadAndValidateConfig(path string) (*Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}

	var cfg Config
	if err := json.Unmarshal(data, &cfg); err != nil {
		return nil, err
	}

	if cfg.Port < 1024 || cfg.Port > 65535 {
		return nil, fmt.Errorf("invalid port")
	}
	if strings.Count(cfg.Version, ".") != 2 {
		return nil, fmt.Errorf("invalid version")
	}
	if len(cfg.Features) == 0 {
		return nil, fmt.Errorf("features cannot be empty")
	}

	return &cfg, nil
}

