const fs = require('fs');

// Create the config file with required data
const configData = {
  app_name: "MyApp",
  version: "1.0.0",
  port: 8080,
  features: ["logging", "auth", "api"]
};

fs.writeFileSync('app_config.json', JSON.stringify(configData, null, 2));

// Load and validate config function
function loadAndValidateConfig(filePath) {
  try {
    // Read the JSON file
    const content = fs.readFileSync(filePath, 'utf-8');

    // Parse the JSON content
    const config = JSON.parse(content);

    // Validate that port is between 1024 and 65535
    if (config.port < 1024 || config.port > 65535) {
      throw new Error(`Invalid port: ${config.port}`);
    }

    // Validate that version contains exactly two dots (X.Y.Z format)
    const dotCount = (config.version.match(/\./g) || []).length;
    if (dotCount !== 2) {
      throw new Error(`Invalid version format: ${config.version}`);
    }

    // Validate that features list is not empty
    if (!Array.isArray(config.features) || config.features.length === 0) {
      throw new Error('Features list is empty');
    }

    return config;
  } catch (error) {
    console.error(`Error loading config: ${error.message}`);
    process.exit(1);
  }
}

// Load and print the result
const config = loadAndValidateConfig('app_config.json');
console.log(`Loaded ${config.app_name} v${config.version} on port ${config.port} with ${config.features.length} features`);

