module benchmark/solution

export type Tree = Leaf | Node(Tree, int, Tree)

export pure func size(t: Tree) -> int =
  match t {
    Leaf => 0,
    Node(left, value, right) => 1 + size(left) + size(right)
  }

export pure func contains(t: Tree, x: int) -> bool =
  match t {
    Leaf => false,
    Node(left, value, right) =>
      if x < value then contains(left, x)
      else if x > value then contains(right, x)
      else true
  }

export pure func insert(t: Tree, x: int) -> Tree =
  match t {
    Leaf => Node(Leaf, x, Leaf),
    Node(left, value, right) =>
      if x < value then Node(insert(left, x), value, right)
      else if x > value then Node(left, value, insert(right, x))
      else t
  }

export pure func isBST(t: Tree, low: int, high: int) -> bool =
  match t {
    Leaf => true,
    Node(left, value, right) =>
      value > low && value < high && isBST(left, low, value) && isBST(right, value, high)
  }

export func insertPreservesBST(x: int) -> bool ! {}
requires { x >= -999999, x <= 999999 }
ensures { result == true }
{
  let t = insert(Leaf, x);
  isBST(t, -999999, 999999)
}

export func insertThenFind(x: int) -> bool ! {}
ensures { result == true }
{
  contains(insert(Leaf, x), x)
}

export func main() -> () ! {IO} {
  let t = insert(insert(insert(Leaf, 5), 3), 7);
  println(show(size(t)));
  println(show(contains(t, 3)));
  println(show(contains(t, 4)));
  println(show(isBST(t, -999999, 999999)));
  println(show(insertPreservesBST(42)));
  println(show(insertThenFind(42)))
}

