from typing import Union

# BST ADT definition
class Leaf:
    pass

class Node:
    def __init__(self, value: int, left: Union['Node', Leaf], right: Union['Node', Leaf]):
        self.value = value
        self.left = left
        self.right = right

# Create a singleton Leaf instance
Leaf_instance = Leaf()

def insert(bst: Union[Node, Leaf], value: int) -> Union[Node, Leaf]:
    """Insert a value into the BST, avoiding duplicates."""
    if isinstance(bst, Leaf):
        return Node(value, Leaf_instance, Leaf_instance)

    if value < bst.value:
        return Node(bst.value, insert(bst.left, value), bst.right)
    elif value > bst.value:
        return Node(bst.value, bst.left, insert(bst.right, value))
    else:
        # Duplicate: return unchanged tree
        return bst

def contains(bst: Union[Node, Leaf], value: int) -> bool:
    """Check if a value exists in the BST."""
    if isinstance(bst, Leaf):
        return False

    if value == bst.value:
        return True
    elif value < bst.value:
        return contains(bst.left, value)
    else:
        return contains(bst.right, value)

def size(bst: Union[Node, Leaf]) -> int:
    """Return the number of nodes in the BST."""
    if isinstance(bst, Leaf):
        return 0
    return 1 + size(bst.left) + size(bst.right)

def isBST(bst: Union[Node, Leaf], lower_bound: int, upper_bound: int) -> bool:
    """Validate that the tree is a proper BST with respect to bounds."""
    if isinstance(bst, Leaf):
        return True

    # Check if current value is within bounds
    if bst.value <= lower_bound or bst.value >= upper_bound:
        return False

    # Recursively check left and right subtrees
    return isBST(bst.left, lower_bound, bst.value) and isBST(bst.right, bst.value, upper_bound)

def insertPreservesBST(value: int) -> bool:
    """Proof that inserting any value preserves the BST property."""
    # Build a test tree
    tree = insert(Leaf_instance, 5)
    tree = insert(tree, 3)
    tree = insert(tree, 7)

    # Insert the value
    tree_after = insert(tree, value)

    # Check that the result is a valid BST
    return isBST(tree_after, -999999, 999999)

def insertThenFind(value: int) -> bool:
    """Proof that inserting a value and then searching for it succeeds."""
    tree = Leaf_instance
    tree = insert(tree, value)
    return contains(tree, value)

def main():
    # Test cases from the problem
    tree = insert(Leaf_instance, 5)
    tree = insert(tree, 3)
    tree = insert(tree, 7)

    print(size(tree))
    print("true" if contains(tree, 3) else "false")
    print("true" if contains(tree, 4) else "false")
    print("true" if isBST(tree, -999999, 999999) else "false")
    print("true" if insertPreservesBST(42) else "false")
    print("true" if insertThenFind(42) else "false")

if __name__ == "__main__":
    main()

