module benchmark/solution

import std/io (println)
import std/string (chars, stringToInt, length as strLength, substring)
import std/list (length, foldl)
import std/option (Option, Some, None)

func isDigit(c: string) -> bool =
  c == "0" || c == "1" || c == "2" || c == "3" || c == "4" ||
  c == "5" || c == "6" || c == "7" || c == "8" || c == "9"

func encodeHelper(cs: [string], current: string, count: int, acc: string) -> string =
  match cs {
    [] => if count == 0 then acc else "${acc}${show(count)}${current}",
    c :: rest =>
      if count == 0 then encodeHelper(rest, c, 1, acc)
      else if c == current then encodeHelper(rest, current, count + 1, acc)
      else encodeHelper(rest, c, 1, "${acc}${show(count)}${current}")
  }

export func encode(s: string) -> string = encodeHelper(chars(s), "", 0, "")

func parseCount(cs: [string], numAcc: string) -> (int, [string]) =
  match cs {
    [] => (0, []),
    c :: rest =>
      if isDigit(c) then parseCount(rest, "${numAcc}${c}")
      else match stringToInt(numAcc) {
        Some(n) => (n, cs),
        None => (0, cs)
      }
  }

func repeatChar(c: string, n: int, acc: string) -> string =
  if n <= 0 then acc else repeatChar(c, n - 1, "${acc}${c}")

func decodeHelper(cs: [string], acc: string) -> string =
  match cs {
    [] => acc,
    _ => {
      let parsed = parseCount(cs, "");
      match parsed {
        (n, remaining) => match remaining {
          [] => acc,
          ch :: rest => decodeHelper(rest, repeatChar(ch, n, acc))
        }
      }
    }
  }

export func decode(s: string) -> string = decodeHelper(chars(s), "")

export func roundtrip(s: string) -> bool = decode(encode(s)) == s

export func singleCharEncode(s: string) -> string = encode(s)

export func main() -> () ! {IO} {
  println(encode("aaabbc"));
  println(encode("xyz"));
  println(decode("3a2b1c"));
  println(decode("1x1y1z"));
  println(show(roundtrip("hello")));
  println(singleCharEncode("q"))
}

