import re


def encode(s: str) -> str:
    if not s:
        return ""
    result = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(f"{count}{s[i - 1]}")
            count = 1
    result.append(f"{count}{s[-1]}")
    return "".join(result)


def decode(s: str) -> str:
    result = []
    for m in re.finditer(r"(\d+)(.)", s):
        result.append(m.group(2) * int(m.group(1)))
    return "".join(result)


def roundtrip(s: str) -> bool:
    return decode(encode(s)) == s


def singleCharEncode(c: str) -> bool:
    return encode(c) == f"1{c}"


def main():
    print(encode("aaabbc"))
    print(encode("xyz"))
    print(decode("3a2b1c"))
    print(decode("1x1y1z"))
    print("true" if roundtrip("hello") else "false")
    print("true" if singleCharEncode("q") else "false")


if __name__ == "__main__":
    main()

