module benchmark/solution

import std/string (startsWith, substring, length)

func dropPrefix(s: string, n: int) -> string ! {} =
  substring(s, n, length(s))

export func toRoman(n: int) -> string ! {}
requires { n >= 1, n <= 3999 }
{
  if n >= 1000 then "M${toRoman(n - 1000)}"
  else if n >= 900 then "CM${toRoman(n - 900)}"
  else if n >= 500 then "D${toRoman(n - 500)}"
  else if n >= 400 then "CD${toRoman(n - 400)}"
  else if n >= 100 then "C${toRoman(n - 100)}"
  else if n >= 90 then "XC${toRoman(n - 90)}"
  else if n >= 50 then "L${toRoman(n - 50)}"
  else if n >= 40 then "XL${toRoman(n - 40)}"
  else if n >= 10 then "X${toRoman(n - 10)}"
  else if n == 9 then "IX"
  else if n >= 5 then "V${toRoman(n - 5)}"
  else if n == 4 then "IV"
  else if n >= 1 then "I${toRoman(n - 1)}"
  else ""
}

func parseRomanRaw(s: string) -> int ! {} =
  if s == "" then 0
  else if startsWith(s, "CM") then 900 + parseRomanRaw(dropPrefix(s, 2))
  else if startsWith(s, "CD") then 400 + parseRomanRaw(dropPrefix(s, 2))
  else if startsWith(s, "XC") then 90 + parseRomanRaw(dropPrefix(s, 2))
  else if startsWith(s, "XL") then 40 + parseRomanRaw(dropPrefix(s, 2))
  else if startsWith(s, "IX") then 9 + parseRomanRaw(dropPrefix(s, 2))
  else if startsWith(s, "IV") then 4 + parseRomanRaw(dropPrefix(s, 2))
  else if startsWith(s, "M") then 1000 + parseRomanRaw(dropPrefix(s, 1))
  else if startsWith(s, "D") then 500 + parseRomanRaw(dropPrefix(s, 1))
  else if startsWith(s, "C") then 100 + parseRomanRaw(dropPrefix(s, 1))
  else if startsWith(s, "L") then 50 + parseRomanRaw(dropPrefix(s, 1))
  else if startsWith(s, "X") then 10 + parseRomanRaw(dropPrefix(s, 1))
  else if startsWith(s, "V") then 5 + parseRomanRaw(dropPrefix(s, 1))
  else if startsWith(s, "I") then 1 + parseRomanRaw(dropPrefix(s, 1))
  else 0

export func fromRoman(s: string) -> int ! {}
ensures { result >= 0, result <= 3999 }
{
  let n = parseRomanRaw(s);
  if n >= 1 && n <= 3999 && toRoman(n) == s then n else 0
}

export func roundtrip(n: int) -> bool ! {}
requires { n >= 1, n <= 3999 }
ensures { result == true }
{
  fromRoman(toRoman(n)) == n
}

export func distinctEncoding(a: int, b: int) -> bool ! {}
requires { a >= 1, a <= 3999, b >= 1, b <= 3999, a != b }
ensures { result == true }
{
  toRoman(a) != toRoman(b)
}

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

module benchmark/solution

type SSet = SNil | SCons(int, SSet)

pure func sLength(s: SSet) -> int =
  match s {
    SNil => 0,
    SCons(_, rest) => 1 + sLength(rest)
  }

pure func isSorted(s: SSet) -> bool =
  match s {
    SNil => true,
    SCons(_, SNil) => true,
    SCons(x, SCons(y, rest)) => x < y && isSorted(SCons(y, rest))
  }

pure func sMerge(a: SSet, b: SSet) -> SSet =
  match a {
    SNil => b,
    SCons(x, xs) => match b {
      SNil => a,
      SCons(y, ys) => if x < y then
        SCons(x, sMerge(xs, b))
      else if x > y then
        SCons(y, sMerge(a, ys))
      else
        SCons(x, sMerge(xs, ys))
