class SNilType:
    def __repr__(self):
        return "SNil"

SNil = SNilType()

class SCons:
    def __init__(self, value, next_node):
        self.value = value
        self.next = next_node

    def __repr__(self):
        return f"SCons({self.value}, {self.next})"

def toStr(s):
    elements = []
    curr = s
    while curr is not SNil:
        elements.append(str(curr.value))
        curr = curr.next
    return "{" + ", ".join(elements) + "}"

def sLength(s):
    count = 0
    curr = s
    while curr is not SNil:
        count += 1
        curr = curr.next
    return count

def isSorted(s):
    if s is SNil or s.next is SNil:
        return True
    curr = s
    while curr.next is not SNil:
        if curr.value >= curr.next.value:
            return False
        curr = curr.next
    return True

def sMerge(s1, s2):
    if s1 is SNil:
        return s2
    if s2 is SNil:
        return s1
    if s1.value < s2.value:
        return SCons(s1.value, sMerge(s1.next, s2))
    elif s1.value > s2.value:
        return SCons(s2.value, sMerge(s1, s2.next))
    else:
        return SCons(s1.value, sMerge(s1.next, s2.next))

def sIntersect(s1, s2):
    if s1 is SNil or s2 is SNil:
        return SNil
    if s1.value < s2.value:
        return sIntersect(s1.next, s2)
    elif s1.value > s2.value:
        return sIntersect(s1, s2.next)
    else:
        return SCons(s1.value, sIntersect(s1.next, s2.next))

def mergePreservesSorted(s1, s2):
    if isSorted(s1) and isSorted(s2):
        return isSorted(sMerge(s1, s2))
    return True

def inclusionExclusion(s1, s2):
    union_len = sLength(sMerge(s1, s2))
    inter_len = sLength(sIntersect(s1, s2))
    s1_len = sLength(s1)
    s2_len = sLength(s2)
    return (union_len + inter_len) == (s1_len + s2_len)

setA = SCons(1, SCons(3, SCons(5, SNil)))
setB = SCons(2, SCons(3, SCons(4, SNil)))

print(toStr(sMerge(setA, setB)))
print(toStr(sIntersect(setA, setB)))
print(sLength(sMerge(setA, setB)))
print(isSorted(sMerge(setA, setB)))
print(mergePreservesSorted(setA, setB))
print(inclusionExclusion(setA, setB))

