pure func exactCsv() -> string =
  "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com"

pure func findField(headers: [string], values: [string], target: string) -> Option[string] =
  match (headers, values) {
    ([], _) => None,
    (_, []) => None,
    (h :: hs, v :: vs) => if trim(h) == target then Some(trim(v)) else findField(hs, vs, target)
  }

pure func validateAge(ageText: string) -> Option[int] =
  match stringToInt(trim(ageText)) {
    Some(n) => if n > 0 then Some(n) else None,
    None => None
  }

pure func isValidEmail(email: string) -> bool =
  contains(email, "@")

pure func parseRow(headers: [string], line: string) -> Option[{name: string, age: int, email: string}] {
  let values = split(line, ",");
  match findField(headers, values, "name") {
    Some(name) => match findField(headers, values, "age") {
      Some(ageText) => match validateAge(ageText) {
        Some(age) => match findField(headers, values, "email") {
          Some(email) => if isValidEmail(email) then Some({name: name, age: age, email: email}) else None,
          None => None
        },
        None => None
      },
      None => None
    },
    None => None
  }
}

pure func userToJson(user: {name: string, age: int, email: string}) -> Json =
  jo([
    kv("name", js(user.name)),
    kv("age", jnum(intToFloat(user.age))),
    kv("email", js(user.email))
  ])

pure func parseRows(headers: [string], lines: [string]) -> [Json] =
  match lines {
    [] => [],
    line :: rest => {
      let cleaned = trim(line);
      if cleaned == "" then parseRows(headers, rest)
      else match parseRow(headers, cleaned) {
        Some(user) => userToJson(user) :: parseRows(headers, rest),
        None => parseRows(headers, rest)
      }
    }
  }

pure func parseCsv(content: string) -> [Json] =
  match split(content, "\n") {
    [] => [],
    headerLine :: rowLines => {
      let headers = split(trim(headerLine), ",");
      parseRows(headers, rowLines)
    }
  }

export func main() -> () ! {IO, FS} {
  let csv = exactCsv();
  writeFile("users.csv", csv);
  let content = readFile("users.csv");
  let users = parseCsv(content);
  let jsonText = encode(ja(users));
  writeFile("users.json", jsonText);
  println("Converted ${length(users)} valid rows to users.json")
}

