package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type User struct {
	Name  string `json:"name"`
	Age   int    `json:"age"`
	Email string `json:"email"`
}

func main() {
	// Create the CSV file with the required content
	csvContent := `name,age,email
Alice,30,alice@example.com
Bob,25,bob@example.com
Carol,35,carol@example.com`

	err := os.WriteFile("users.csv", []byte(csvContent), 0644)
	if err != nil {
		fmt.Println("Error writing CSV file:", err)
		return
	}

	// Open and parse the CSV file
	file, err := os.Open("users.csv")
	if err != nil {
		fmt.Println("Error opening CSV file:", err)
		return
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	var users []User
	validCount := 0

	// Skip the header line
	if !scanner.Scan() {
		fmt.Println("Error reading header")
		return
	}

	// Parse each data row
	for scanner.Scan() {
		line := scanner.Text()
		fields := strings.Split(line, ",")

		// Validate field count
		if len(fields) != 3 {
			continue
		}

		name := fields[0]
		ageStr := fields[1]
		email := fields[2]

		// Validate age: must be a positive integer
		age, err := strconv.Atoi(ageStr)
		if err != nil || age <= 0 {
			continue
		}

		// Validate email: must contain "@" symbol
		if !strings.Contains(email, "@") {
			continue
		}

		// Add valid row to users list
		users = append(users, User{
			Name:  name,
			Age:   age,
			Email: email,
		})
		validCount++
	}

	// Convert users to JSON
	jsonData, err := json.Marshal(users)
	if err != nil {
		fmt.Println("Error marshaling JSON:", err)
		return
	}

	// Write JSON to file
	err = os.WriteFile("users.json", jsonData, 0644)
	if err != nil {
		fmt.Println("Error writing JSON file:", err)
		return
	}

	// Print the result message
	fmt.Printf("Converted %d valid rows to users.json\n", validCount)
}

