from typing import Callable, TypeVar, Any
from functools import wraps

# Effect annotations
def pure(func: Callable) -> Callable:
    """Marks a function as pure (no side effects)"""
    func._effects = set()
    return func

def io_effect(func: Callable) -> Callable:
    """Marks a function as having IO effects"""
    func._effects = {'IO'}
    return func

def fs_io_effect(func: Callable) -> Callable:
    """Marks a function as having both FS and IO effects"""
    func._effects = {'IO', 'FS'}
    return func

# Pure function - no side effects
@pure
def computeSum(a: int, b: int) -> int:
    """Returns sum of two numbers. Pure function."""
    return a + b

# IO function - prints output
@io_effect
def printSum(a: int, b: int) -> None:
    """Computes sum and prints it. IO effect."""
    result = computeSum(a, b)
    print(f"Sum: {result}")

# IO + FS function - writes to file
@fs_io_effect
def logToFile(filename: str, message: str) -> None:
    """Writes message to file. IO and FS effects."""
    with open(filename, 'w') as f:
        f.write(message)

def main() -> None:
    """Main function demonstrating effect tracking."""
    # Call computeSum (pure) and store result
    result = computeSum(10, 20)

    # Call printSum (IO effect)
    printSum(10, 20)

    # Call logToFile (IO + FS effects)
    logToFile("output.txt", "Sum was 30")

    # Print done
    print("Done")

if __name__ == "__main__":
    main()

