module benchmark/solution

pure func contains(x: int, xs: [int]) -> bool =
  match xs {
    [] => false,
    y :: rest => if x == y then true else contains(x, rest)
  }

pure func enqueue(x: int, queue: [int]) -> [int] =
  match queue {
    [] => [x],
    y :: rest => y :: enqueue(x, rest)
  }

pure func neighbors(graph: [(int, [int])], node: int) -> [int] =
  match graph {
    [] => [],
    (n, ns) :: rest => if n == node then ns else neighbors(rest, node)
  }

pure func enqueueManyNotVisited(xs: [int], queue: [int], visited: [int]) -> [int] =
  match xs {
    [] => queue,
    x :: rest =>
      if contains(x, visited)
      then enqueueManyNotVisited(rest, queue, visited)
      else enqueueManyNotVisited(rest, enqueue(x, queue), visited)
  }

pure func bfsLoop(graph: [(int, [int])], queue: [int], visited: [int], order: [int]) -> [int] =
  match queue {
    [] => order,
    node :: rest =>
      if contains(node, visited) then bfsLoop(graph, rest, visited, order)
      else {
        let newVisited = enqueue(node, visited);
        let ns = neighbors(graph, node);
        let newQueue = enqueueManyNotVisited(ns, rest, newVisited);
        let newOrder = enqueue(node, order);
        bfsLoop(graph, newQueue, newVisited, newOrder)
      }
  }

