	for _, v := range list {
		if v == x {
			return true
		}
	}
	return false
}

func bfs(graph map[int][]int, start int) []int {
	visited := []int{}
	queue := []int{start}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		if contains(node, visited) {
			continue
		}

		visited = append(visited, node)

		for _, neighbor := range graph[node] {
			if !contains(neighbor, visited) {
				queue = append(queue, neighbor)
			}
		}
	}

	return visited
