// UnaryFunc is a function type that takes an int and returns an int
type UnaryFunc func(x int) int

// pipe returns a function that applies f first, then g (computing g(f(x)))
func pipe(f, g UnaryFunc) UnaryFunc {
	return func(x int) int {
		return g(f(x))
	}
}

