	sub4 := func(x int) int {
		return subtract(x, 4)
	}

	// Create double using partial application (multiplies input by 2)
	double := func(x int) int {
		return multiply(2, x)
	}

	// Create piped function: subtract 4 first, then double
	sub4_then_double := pipe(sub4, double)

