  match lines {
    [] => [],
    line :: rest => {
      let others = collectUsers(rest);
      if contains(line, "User logged") then {
        let user = extractUser(line);
        if user == "" then others
        else if containsStr(others, user) then others
        else user :: others
      } else others
    }
  }

func containsStr(xs: [string], s: string) -> bool =
  match xs {
    [] => false,
    x :: rest => if x == s then true else containsStr(rest, s)
  }

func cmpStr(a: string, b: string) -> int {
  if a < b then -1
  else if a > b then 1
  else 0
}

