from __future__ import annotations

from pathlib import Path


LOG_LINES = [
    "2024-10-29 10:00:00 INFO User logged in: alice",
    "2024-10-29 10:01:15 ERROR Database connection failed",
    "2024-10-29 10:02:30 INFO User logged in: bob",
    "2024-10-29 10:03:45 WARNING High memory usage: 85%",
    "2024-10-29 10:05:00 ERROR API timeout: /users endpoint",
    "2024-10-29 10:06:15 INFO User logged out: alice",
]


def write_log_file(path: Path) -> None:
    path.write_text("\n".join(LOG_LINES), encoding="utf-8")


def analyze_log(path: Path) -> tuple[int, dict[str, int], list[str]]:
    level_counts = {"INFO": 0, "ERROR": 0, "WARNING": 0}
    users: set[str] = set()

    for line in path.read_text(encoding="utf-8").splitlines():
        _, _, level, message = line.split(" ", 3)
        if level in level_counts:
            level_counts[level] += 1

        if ":" in message:
            tail = message.rsplit(":", 1)[1].strip()
            if tail in {"alice", "bob"}:
                users.add(tail)

    return len(LOG_LINES), level_counts, sorted(users)


def main() -> None:
    path = Path("app.log")
    write_log_file(path)
    total, level_counts, users = analyze_log(path)

    print(f"Total log entries: {total}")
    for level in ("INFO", "ERROR", "WARNING"):
        count = level_counts[level]
        percentage = (count * 100 + total // 2) // total
        print(f"{level}: {count} ({percentage}%)")
    print(f"Unique users: {', '.join(users)}")


if __name__ == "__main__":
    main()

