    Var(name) => lookup(name, env),
    Add(left, right) => eval(left, env) + eval(right, env),
    Mul(left, right) => eval(left, env) * eval(right, env),
    Let(name, e1, e2) => {
      let value = eval(e1, env);
      let newEnv = (name, value) :: env;
      eval(e2, newEnv)
    }
  }

export func main() -> () ! {IO} {
