from dataclasses import dataclass
from typing import Union


@dataclass
class Num:
    value: int


@dataclass
class Var:
    name: str


@dataclass
class Add:
    left: "Expr"
    right: "Expr"


@dataclass
class Mul:
    left: "Expr"
    right: "Expr"


@dataclass
class Let:
    name: str
    expr: "Expr"
    body: "Expr"


Expr = Union[Num, Var, Add, Mul, Let]
Env = list[tuple[str, int]]


def lookup(name: str, env: Env) -> int:
    for n, v in reversed(env):
        if n == name:
            return v
    raise NameError(f"Unbound variable: {name}")


def eval(expr: Expr, env: Env) -> int:
    match expr:
        case Num(value):
            return value
        case Var(name):
            return lookup(name, env)
        case Add(left, right):
            return eval(left, env) + eval(right, env)
        case Mul(left, right):
            return eval(left, env) * eval(right, env)
        case Let(name, e1, e2):
            val = eval(e1, env)
            return eval(e2, env + [(name, val)])


def main():
    program = Let("x", Num(5), Let("y", Add(Var("x"), Num(3)), Mul(Var("x"), Var("y"))))
    result = eval(program, [])
    print(result)


if __name__ == "__main__":
