package main

import "fmt"

// Tree interface defines our algebraic data type
type Tree interface {
	isTree()
}

// Leaf represents a leaf node with a single value
type Leaf struct {
	value int
}

func (l *Leaf) isTree() {}

// Node represents an internal node with left subtree, value, and right subtree
type Node struct {
	left  Tree
	value int
	right Tree
}

func (n *Node) isTree() {}

// tree_sum calculates the sum of all values in the tree using pattern matching
func tree_sum(t Tree) int {
	// Pattern match on the tree type
	switch v := t.(type) {
	case *Leaf:
		// Match Leaf(v): return v
		return v.value
	case *Node:
		// Match Node(l, v, r): return tree_sum(l) + v + tree_sum(r)
		return tree_sum(v.left) + v.value + tree_sum(v.right)
	}
	// This should never be reached due to exhaustiveness
	return 0
}

// find_max finds the maximum value in the tree using nested patterns and guards
func find_max(t Tree) int {
	switch v := t.(type) {
	case *Leaf:
		// Match Leaf(v): return v
		return v.value
	case *Node:
		// Match Node with guards to find maximum value
		leftMax := find_max(v.left)
		rightMax := find_max(v.right)

		// Compare all three values and return the maximum
		max := leftMax
		if v.value > max {
			max = v.value
		}
		if rightMax > max {
			max = rightMax
		}
		return max
	}
	// This should never be reached due to exhaustiveness
	return 0
}

func main() {
	// Create sample tree: Node(Leaf(1), 5, Node(Leaf(3), 7, Leaf(2)))
	tree := &Node{
		left:  &Leaf{value: 1},
		value: 5,
		right: &Node{
			left:  &Leaf{value: 3},
			value: 7,
			right: &Leaf{value: 2},
		},
	}

	// Calculate sum: 1 + 5 + 3 + 7 + 2 = 18
	sum := tree_sum(tree)

	// Find maximum: 7
	max := find_max(tree)

	// Print results
	fmt.Printf("Sum: %d\n", sum)
	fmt.Printf("Max: %d\n", max)
}

