def run_length_encode(chars: list[str]) -> list[tuple[int, str]]:
    if not chars:
        return []

    def helper(lst: list[str], current: str, count: int, acc: list[tuple[int, str]]) -> list[tuple[int, str]]:
        if not lst:
            return acc + [(count, current)]
        if lst[0] == current:
            return helper(lst[1:], current, count + 1, acc)
        else:
            return helper(lst[1:], lst[0], 1, acc + [(count, current)])

    return helper(chars[1:], chars[0], 1, [])


def main():
    data = ['a', 'a', 'a', 'b', 'b', 'c', 'c', 'c', 'c', 'a']
    encoded = run_length_encode(data)
    parts = ", ".join(f"({count}, {char})" for count, char in encoded)
