package main

import "fmt"

// State represents the elevator state using sum type via interface
type State interface {
	isState()
}

// Idle state: elevator at a floor with no active movement
type Idle struct {
	Floor int
}

func (Idle) isState() {}

// Moving state: elevator in transit between floors
type Moving struct {
	Current int
	Target  int
}

func (Moving) isState() {}

// DoorOpen state: elevator at a floor with door open
type DoorOpen struct {
	Floor int
	Timer int // seconds until door closes
}

func (DoorOpen) isState() {}

// Event represents elevator events using sum type via interface
type Event interface {
	isEvent()
}

// Call event: someone calls the elevator to a floor
type Call struct {
	Floor int
}

func (Call) isEvent() {}

// Tick event: one second passes
type Tick struct {
}

func (Tick) isEvent() {}

// Arrive event: elevator reaches target floor
type Arrive struct {
}

func (Arrive) isEvent() {}

// Transition applies an event to a state and returns the new state
func Transition(state State, event Event) State {
	switch s := state.(type) {
	case Idle:
		switch e := event.(type) {
		case Call:
			if e.Floor == s.Floor {
				return DoorOpen{Floor: s.Floor, Timer: 3}
			}
			return Moving{Current: s.Floor, Target: e.Floor}
		case Tick:
			return s
		case Arrive:
			return s
		}
	case Moving:
		switch event.(type) {
		case Tick:
			return s
		case Arrive:
			return DoorOpen{Floor: s.Target, Timer: 3}
		case Call:
			return s
		}
	case DoorOpen:
		switch event.(type) {
		case Tick:
			if s.Timer > 1 {
				return DoorOpen{Floor: s.Floor, Timer: s.Timer - 1}
			}
			return Idle{Floor: s.Floor}
		case Call:
			return s
		case Arrive:
			return s
		}
	}
	return state
}

// Display returns a formatted string representation of the state
func Display(state State) string {
	switch s := state.(type) {
	case Idle:
		return fmt.Sprintf("IDLE @ floor %d", s.Floor)
	case Moving:
		return fmt.Sprintf("MOVING %d -> %d", s.Current, s.Target)
	case DoorOpen:
		return fmt.Sprintf("DOOR_OPEN @ floor %d (%dsec)", s.Floor, s.Timer)
	}
	return ""
}

func main() {
	// Start with Idle(1)
	state := State(Idle{Floor: 1})

	// Apply Call(5) event
	state = Transition(state, Call{Floor: 5})
	fmt.Println(Display(state))

	// Apply 2 Tick events
	state = Transition(state, Tick{})
	fmt.Println(Display(state))

	state = Transition(state, Tick{})
	fmt.Println(Display(state))

	// Apply Arrive event
	state = Transition(state, Arrive{})
	fmt.Println(Display(state))

	// Apply 4 Tick events
	state = Transition(state, Tick{})
	fmt.Println(Display(state))

	state = Transition(state, Tick{})
	fmt.Println(Display(state))

	state = Transition(state, Tick{})
	fmt.Println(Display(state))

	state = Transition(state, Tick{})
	fmt.Println(Display(state))

	// Apply Call(1) event
	state = Transition(state, Call{Floor: 1})
	fmt.Println(Display(state))
}

