import sys
from dataclasses import dataclass
from typing import Union

# 1. Define State Type
@dataclass(frozen=True)
class Idle:
    floor: int

@dataclass(frozen=True)
class Moving:
    current_floor: int
    target_floor: int

@dataclass(frozen=True)
class DoorOpen:
    floor: int
    timer: int

State = Union[Idle, Moving, DoorOpen]

# 2. Define Event Type
@dataclass(frozen=True)
class Call:
    floor: int

@dataclass(frozen=True)
class Tick:
    pass

@dataclass(frozen=True)
class Arrive:
    pass

Event = Union[Call, Tick, Arrive]

# 3. Implement transition function
def transition(state: State, event: Event) -> State:
    """
    Takes a state and an event, and returns the new state.
    """
    match (state, event):
        # - Idle(floor) + Call(target): If target == floor, go to DoorOpen(floor, 3);
        #   else go to Moving(floor, target)
        case (Idle(floor), Call(target)):
            if target == floor:
                return DoorOpen(floor, 3)
            else:
                return Moving(floor, target)

        # - Moving(cur, target) + Tick: Stay in Moving (simulating movement)
        case (Moving(_, _), Tick()):
            return state

        # - Moving(cur, target) + Arrive: Go to DoorOpen(target, 3)
        case (Moving(_, target), Arrive()):
            return DoorOpen(target, 3)

        # - DoorOpen(floor, timer) + Tick: If timer > 1, decrement timer;
        #   else go to Idle(floor)
        case (DoorOpen(floor, timer), Tick()):
            if timer > 1:
                return DoorOpen(floor, timer - 1)
            else:
                return Idle(floor)

        # - Any other combination: Return current state unchanged
        case _:
            return state

# 4. Implement display function
def display(state: State) -> str:
    """
    Takes a state and returns a formatted string representation.
    """
    match state:
        case Idle(floor):
            return f"IDLE @ floor {floor}"
        case Moving(current, target):
            return f"MOVING {current} -> {target}"
        case DoorOpen(floor, timer):
            return f"DOOR_OPEN @ floor {floor} ({timer}sec)"
        case _:
            # This should be unreachable if all states are handled
            return "Unknown state"

# 5. Main simulation
def main():
    """
    Runs the elevator simulation.
    """
    state: State = Idle(1)

    events: list[Event] = [
        Call(5),
        Tick(),
        Tick(),
        Arrive(),
        Tick(),
        Tick(),
        Tick(),
        Tick(),
        Call(1),
    ]

    for event in events:
        state = transition(state, event)
        print(display(state))

if __name__ == "__main__":
    main()

