type Result[a] = Ok(a) | Err(string)

pure func price(code: int) -> Result[int] =
  match code {
    1 => Ok(125),
    2 => Ok(75),
    3 => Ok(100),
    _ => Err("unknown_item")
  }

pure func step(state: State, event: Event) -> Result[State] =
  match (state, event) {
    (Idle, Insert(n)) => Ok(HasCredit(n)),
    (Idle, Select(_)) => Err("no_credit"),
    (Idle, DispenseDone) => Err("not_dispensing"),

    (HasCredit(c), Insert(n)) => Ok(HasCredit(c + n)),
    (HasCredit(c), Select(code)) =>
      match price(code) {
        Ok(p) => if c < p then Err("insufficient_funds") else Ok(Dispensing(c - p)),
        Err(reason) => Err(reason)
      },
    (HasCredit(_), DispenseDone) => Err("not_dispensing"),

    (Dispensing(_), Insert(_)) => Err("busy"),
    (Dispensing(_), Select(_)) => Err("busy"),
    (Dispensing(_), DispenseDone) => Ok(Idle)
  }

pure func formatState(state: State) -> string =
