// Idle is the initial state with no credit.
type Idle struct{}

func (Idle) isState() {}

// HasCredit is the state when money has been inserted.
type HasCredit struct {
	cents int
}

func (HasCredit) isState() {}

// Dispensing is the state when an item is being dispensed.
type Dispensing struct {
	change int
}

func (Dispensing) isState() {}

// Event represents the actions that can be performed on the vending machine.
type Event interface {
	isEvent()
}

// Insert represents inserting coins.
type Insert struct {
	cents int
}

func (Insert) isEvent() {}

// Select represents choosing an item.
type Select struct {
	code int
}

func (Select) isEvent() {}

// DispenseDone represents the completion of dispensing an item.
type DispenseDone struct{}

func (DispenseDone) isEvent() {}

// Result holds the outcome of a state transition.
type Result struct {
	state State
	err   string
}

// Ok creates a successful result with a new state.
func Ok(s State) Result {
	return Result{state: s}
}

// Err creates a failed result with an error reason.
func Err(reason string) Result {
	return Result{err: reason}
}

// price returns the cost of an item by its code.
func price(code int) int {
	switch code {
	case 1: // cola
		return 125
	case 2: // chips
		return 75
	case 3: // water
		return 100
	default:
		return -1 // Indicates an unknown item
	}
}

// step is the core transition function for the state machine.
func step(state State, event Event) Result {
	switch s := state.(type) {
	case Idle:
		switch e := event.(type) {
		case Insert:
			return Ok(HasCredit{cents: e.cents})
		case Select:
			return Err("no_credit")
		case DispenseDone:
			return Err("not_dispensing")
		}
	case HasCredit:
		switch e := event.(type) {
		case Insert:
			return Ok(HasCredit{cents: s.cents + e.cents})
		case Select:
			itemPrice := price(e.code)
			if itemPrice == -1 {
				return Err("unknown_item")
			}
			if s.cents < itemPrice {
				return Err("insufficient_funds")
			}
			return Ok(Dispensing{change: s.cents - itemPrice})
		case DispenseDone:
			return Err("not_dispensing")
		}
	case Dispensing:
		switch event.(type) {
		case Insert, Select:
			return Err("busy")
		case DispenseDone:
			return Ok(Idle{})
		}
	}
	// This should be unreachable if all combinations are handled.
	return Err("unhandled state or event")
}

// printResult prints the formatted outcome of a transition.
func printResult(r Result) {
	if r.err != "" {
		fmt.Printf("err: %s\n", r.err)
		return
	}

	switch s := r.state.(type) {
	case Idle:
		fmt.Println("ok: IDLE")
	case HasCredit:
		fmt.Printf("ok: CREDIT(%d)\n", s.cents)
	case Dispensing:
		fmt.Printf("ok: DISPENSING(%d)\n", s.change)
	}
}

func main() {
	currentState := State(Idle{})

	events := []Event{
		Insert{cents: 50},
		Select{code: 1},
		Insert{cents: 100},
		Select{code: 1},
		Insert{cents: 50},
		DispenseDone{},
		Select{code: 2},
		Insert{cents: 100},
		Select{code: 2},
		DispenseDone{},
	}

	for _, event := range events {
		result := step(currentState, event)
		printResult(result)
		if result.err == "" { // On success, update the state.
			currentState = result.state
		}
		// On error, the state remains unchanged.
	}
}

