from dataclasses import dataclass
from typing import Generic, TypeVar

# --- Algebraic Data Types (ADTs) for State, Event, and Result ---

# State ADT
@dataclass
class Idle:
    pass

@dataclass
class HasCredit:
    cents: int

@dataclass
class Dispensing:
    change: int

State = Idle | HasCredit | Dispensing

# Event ADT
@dataclass
class Insert:
    cents: int

@dataclass
class Select:
    code: int

@dataclass
class DispenseDone:
    pass

Event = Insert | Select | DispenseDone

# Result ADT
T = TypeVar('T')
E = TypeVar('E')

@dataclass
class Ok(Generic[T]):
    value: T

@dataclass
class Err(Generic[E]):
    reason: E

Result = Ok[State] | Err[str]

# --- Constants ---
PRICES = {
    1: 125,  # cola
    2: 75,   # chips
    3: 100,  # water
}

# --- State Transition Function ---

def step(state: State, event: Event) -> Result:
    match (state, event):
        # Transitions from Idle state
        case (Idle(), Insert(n)):
            return Ok(HasCredit(n))
        case (Idle(), Select(_)):
            return Err("no_credit")
        case (Idle(), DispenseDone()):
            return Err("not_dispensing")

        # Transitions from HasCredit state
        case (HasCredit(c), Insert(n)):
            return Ok(HasCredit(c + n))
        case (HasCredit(c), Select(code)):
            if code not in PRICES:
                return Err("unknown_item")
            price = PRICES[code]
            if c < price:
                return Err("insufficient_funds")
            return Ok(Dispensing(c - price))
        case (HasCredit(_), DispenseDone()):
            return Err("not_dispensing")

        # Transitions from Dispensing state
        case (Dispensing(_), Insert(_)):
            return Err("busy")
        case (Dispensing(_), Select(_)):
            return Err("busy")
        case (Dispensing(_), DispenseDone()):
            return Ok(Idle())

# --- Simulation ---

def main():
    events: list[Event] = [
        Insert(50),
        Select(1),
        Insert(100),
        Select(1),
        Insert(50),
        DispenseDone(),
        Select(2),
        Insert(100),
        Select(2),
        DispenseDone(),
    ]

