pure func diff(expr: Expr, v: string) -> Expr =
  match expr {
    Const(_) => Const(0),
    Var(name) => if name == v then Const(1) else Const(0),
    Add(a, b) => Add(diff(a, v), diff(b, v)),
    Mul(a, b) => Add(Mul(a, diff(b, v)), Mul(b, diff(a, v)))
  }

pure func simplify(expr: Expr) -> Expr =
