    Const(n) => Const(n),
    Var(name) => Var(name),
    Add(a, b) => {
      let sa = simplify(a);
      let sb = simplify(b);
      match (sa, sb) {
        (Const(0), e) => e,
        (e, Const(0)) => e,
        (Const(x), Const(y)) => Const(x + y),
        _ => Add(sa, sb)
      }
