      let sb = simplify(b);
      match (sa, sb) {
        (Const(0), _) => Const(0),
        (_, Const(0)) => Const(0),
        (Const(1), e) => e,
        (e, Const(1)) => e,
        (Const(x), Const(y)) => Const(x * y),
        _ => Mul(sa, sb)
      }
    }
  }

