pure func treeDepth(tree: Tree) -> int =
  match tree {
    Leaf(_) => 1,
    Node(left, _, right) => {
      let leftDepth = treeDepth(left);
      let rightDepth = treeDepth(right);
      let maxDepth = if leftDepth > rightDepth then leftDepth else rightDepth;
