package main

import (
	"fmt"
	"strings"
)

// Tree interface represents a binary tree
type Tree interface {
	isTree()
}

// Leaf represents a leaf node with a single integer value
type Leaf struct {
	value int
}

func (l Leaf) isTree() {}

// Node represents an internal node with left subtree, value, and right subtree
type Node struct {
	left  Tree
	value int
	right Tree
}

func (n Node) isTree() {}

// mapTree recursively applies a function to all values in the tree
func mapTree(fn func(int) int, tree Tree) Tree {
	switch t := tree.(type) {
	case Leaf:
		return Leaf{value: fn(t.value)}
	case Node:
		return Node{
			left:  mapTree(fn, t.left),
			value: fn(t.value),
			right: mapTree(fn, t.right),
		}
	}
	return nil
}

// foldTree performs an in-order fold over tree values
func foldTree(fn func(int, int) int, acc int, tree Tree) int {
	switch t := tree.(type) {
	case Leaf:
		return fn(acc, t.value)
	case Node:
		acc = foldTree(fn, acc, t.left)
		acc = fn(acc, t.value)
		acc = foldTree(fn, acc, t.right)
		return acc
	}
	return acc
}

// treeToList performs in-order traversal returning list of integers
func treeToList(tree Tree) []int {
	var result []int
	var traverse func(Tree)
	traverse = func(t Tree) {
		switch tree := t.(type) {
		case Leaf:
			result = append(result, tree.value)
		case Node:
			traverse(tree.left)
			result = append(result, tree.value)
			traverse(tree.right)
		}
	}
	traverse(tree)
	return result
}

// treeDepth returns the maximum depth of the tree
func treeDepth(tree Tree) int {
	switch t := tree.(type) {
	case Leaf:
		return 1
	case Node:
		leftDepth := treeDepth(t.left)
		rightDepth := treeDepth(t.right)
		if leftDepth > rightDepth {
			return 1 + leftDepth
		}
		return 1 + rightDepth
	}
	return 0
}

// Helper functions
func double(x int) int {
	return x * 2
}

func add(a, b int) int {
	return a + b
}

// formatList formats a list as [1, 2, 3]
func formatList(lst []int) string {
	var parts []string
	for _, v := range lst {
		parts = append(parts, fmt.Sprintf("%d", v))
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func main() {
	// Create the test tree:
	//       4
	//      / \
	//     2   6
	//    / \ / \
	//   1  3 5  7
	tree := Node{
		left: Node{
			left:  Leaf{value: 1},
			value: 2,
			right: Leaf{value: 3},
		},
		value: 4,
		right: Node{
			left:  Leaf{value: 5},
			value: 6,
			right: Leaf{value: 7},
		},
	}

	// Print results
	fmt.Println(formatList(treeToList(tree)))
	fmt.Println(formatList(treeToList(mapTree(double, tree))))
	fmt.Println(foldTree(add, 0, tree))
	fmt.Println(treeDepth(tree))
}

