// Tree type definition
const Leaf = (value) => ({ type: 'Leaf', value });
const Node = (left, value, right) => ({ type: 'Node', left, value, right });

// mapTree: Recursively apply function to all values in tree
const mapTree = (fn, tree) => {
  if (tree.type === 'Leaf') {
    return Leaf(fn(tree.value));
  } else {
    return Node(
      mapTree(fn, tree.left),
      fn(tree.value),
      mapTree(fn, tree.right)
    );
  }
};

// foldTree: In-order fold over tree values
const foldTree = (fn, acc, tree) => {
  if (tree.type === 'Leaf') {
    return fn(acc, tree.value);
  } else {
    const leftResult = foldTree(fn, acc, tree.left);
    const nodeResult = fn(leftResult, tree.value);
    return foldTree(fn, nodeResult, tree.right);
  }
};

// treeToList: In-order traversal returning list of integers
const treeToList = (tree) => {
  const result = [];
  const traverse = (node) => {
    if (node.type === 'Leaf') {
      result.push(node.value);
    } else {
      traverse(node.left);
      result.push(node.value);
      traverse(node.right);
    }
  };
  traverse(tree);
  return result;
};

// treeDepth: Return maximum depth of tree (Leaf has depth 1)
const treeDepth = (tree) => {
  if (tree.type === 'Leaf') {
    return 1;
  } else {
    return 1 + Math.max(treeDepth(tree.left), treeDepth(tree.right));
  }
};

