module benchmark/solution

import std/option (Option, Some, None)

type Type = TVar(string) | TInt | TBool | TFunc(Type, Type)
type Binding = Bind(string, Type)

pure func lookupSubst(name: string, subst: [Binding]) -> Option[Type] =
  match subst {
    [] => None,
    Bind(n, t) :: rest => if n == name then Some(t) else lookupSubst(name, rest)
  }

pure func apply(subst: [Binding], t: Type) -> Type =
  match t {
    TVar(name) => match lookupSubst(name, subst) {
      Some(t2) => match t2 {
        TVar(name2) => if name == name2 then TVar(name) else apply(subst, t2),
        _ => apply(subst, t2)
      },
      None => TVar(name)
    },
    TInt => TInt,
    TBool => TBool,
    TFunc(arg, res) => TFunc(apply(subst, arg), apply(subst, res))
  }

pure func unify(t1: Type, t2: Type) -> Option[[Binding]] =
  match t1 {
    TVar(a) => Some([Bind(a, t2)]),
    TInt => match t2 {
      TInt => Some([]),
      TVar(a) => Some([Bind(a, TInt)]),
      _ => None
    },
    TBool => match t2 {
      TBool => Some([]),
      TVar(a) => Some([Bind(a, TBool)]),
      _ => None
    },
    TFunc(a1, r1) => match t2 {
      TVar(a) => Some([Bind(a, t1)]),
      TFunc(a2, r2) => match unify(a1, a2) {
        Some(s1) => match unify(r1, r2) {
          Some(s2) => Some(s1 ++ s2),
          None => None
        },
        None => None
      },
      _ => None
    }
  }

pure func showType(t: Type) -> string =
  match t {
    TVar(name) => "TVar(${name})",
    TInt => "TInt",
    TBool => "TBool",
    TFunc(arg, res) => "TFunc(${showType(arg)}, ${showType(res)})"
  }

func printBinding(name: string, subst: [Binding]) -> () ! {IO} {
  match lookupSubst(name, subst) {
    Some(t) => println("${name} = ${showType(apply(subst, t))}"),
    None => println("${name} = <unbound>")
  }
}

export func main() -> () ! {IO} {
  let t1 = TFunc(TVar("a"), TInt);
  let t2 = TFunc(TBool, TVar("b"));
  match unify(t1, t2) {
    Some(subst) => {
      printBinding("a", subst);
      printBinding("b", subst)
    },
    None => println("Types do not unify")
  }
}

